package com.justenoughmods.achievementguide.integration.prehistoric;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.effect.*;
import net.minecraft.nbt.CompoundTag;
public final class WorldPrehistoricQuestDart {
 public static final class Shot {public final ServerPlayer actor;public final ItemStack weapon;public final net.minecraft.world.item.Item ammo;public final int count;public final List<Projectile> projectiles=new ArrayList<>();public Shot(ServerPlayer actor,ItemStack weapon,net.minecraft.world.item.Item ammo,int count){this.actor=actor;this.weapon=weapon;this.ammo=ammo;this.count=count;}}
 public static final class Hit {public final ServerPlayer actor;public final Projectile projectile;public final LivingEntity target;public final float health,absorption;public boolean poison,damage;public Hit(ServerPlayer actor,Projectile projectile,LivingEntity target){this.actor=actor;this.projectile=projectile;this.target=target;health=target.getHealth();absorption=target.getAbsorptionAmount();}}
 public record Damage(Hit hit,LivingEntity target,net.minecraft.world.damagesource.DamageSource source,float vitality){}
 private static final class DamageCalls {final ArrayDeque<java.util.Optional<Damage>> calls=new ArrayDeque<>();int overflow;}
 private static final ThreadLocal<DamageCalls> DAMAGES=ThreadLocal.withInitial(DamageCalls::new);
 public static void damageScopeBegin(LivingEntity target,net.minecraft.world.damagesource.DamageSource source,float amount){if(!(target.level() instanceof net.minecraft.server.level.ServerLevel))return;var calls=DAMAGES.get();if(calls.overflow>0||calls.calls.size()>=32){calls.overflow++;return;}calls.calls.push(java.util.Optional.ofNullable(damageBefore(target,source,amount)));}
 public static void damageScopeEnd(LivingEntity target,boolean accepted){if(!(target.level() instanceof net.minecraft.server.level.ServerLevel))return;var calls=DAMAGES.get();if(calls.overflow>0){calls.overflow--;return;}var before=calls.calls.isEmpty()?null:calls.calls.pop().orElse(null);if(calls.calls.isEmpty())DAMAGES.remove();if(before!=null&&before.target()==target)damageAfter(before,accepted);}
 public static boolean inImpact(){return HIT.get()!=null;}
 public static Damage damageBefore(LivingEntity target,net.minecraft.world.damagesource.DamageSource source,float amount){var hit=HIT.get();return hit!=null&&target==hit.target&&source.getDirectEntity()==hit.projectile&&source.getEntity()==hit.actor&&Float.isFinite(amount)&&amount>0?new Damage(hit,target,source,target.getHealth()+target.getAbsorptionAmount()):null;}
 public static void damageAfter(Damage before,boolean accepted){if(before!=null&&accepted&&Float.isFinite(before.vitality())&&Float.isFinite(before.target().getHealth()+before.target().getAbsorptionAmount())&&before.target().getHealth()+before.target().getAbsorptionAmount()<before.vitality())before.hit().damage=true;}
 private static final ThreadLocal<Shot> SHOT=new ThreadLocal<>();private static final ThreadLocal<Hit> HIT=new ThreadLocal<>();
 public static void clear(){SHOT.remove();HIT.remove();DAMAGES.remove();}
 private WorldPrehistoricQuestDart(){}
 public static void beforeShot(Entity source,ItemStack weapon){SHOT.remove();var actor=WorldPrehistoricQuestProof.actor(source);if(actor==null || actor.getMainHandItem()!=weapon || !WorldPrehistoricQuestProof.id(weapon).equals("unearthed_journey:bamboo_blowgun") || !WorldPrehistoricQuestProof.id(actor.getOffhandItem()).equals("unearthed_journey:tipped_blow_dart"))return;var ammo=actor.getOffhandItem().getItem();SHOT.set(new Shot(actor,weapon,ammo,WorldPrehistoricQuestProof.countType(actor.getInventory(),ammo)));}
 public static void accepted(Entity entity){var s=SHOT.get();if(s!=null && entity instanceof Projectile projectile && projectile.getOwner()==s.actor && WorldPrehistoricQuestProof.id(projectile).equals("unearthed_journey:tipped_blow_dart_projectile") && s.projectiles.size()<8)s.projectiles.add(projectile);}
 public static void afterShot(){var s=SHOT.get();SHOT.remove();if(s==null || WorldPrehistoricQuestProof.actor(s.actor)==null || s.count-WorldPrehistoricQuestProof.countType(s.actor.getInventory(),s.ammo)!=1)return;for(var projectile:s.projectiles)if(!projectile.isRemoved() && projectile.getOwner()==s.actor && s.actor.serverLevel().getEntity(projectile.getUUID())==projectile){var t=new CompoundTag();t.putUUID("actor",s.actor.getUUID());t.putUUID("projectile",projectile.getUUID());t.putString("ammo","unearthed_journey:tipped_blow_dart");t.putString("weapon","unearthed_journey:bamboo_blowgun");projectile.getPersistentData().put(WorldPrehistoricQuestProof.ROOT,t);}}
 public static void beforeHit(Projectile projectile,Entity victim){HIT.remove();var actor=WorldPrehistoricQuestProof.actor(projectile.getOwner());var t=WorldPrehistoricQuestProof.data(projectile);if(actor!=null && victim instanceof LivingEntity target && target.isAlive() && WorldPrehistoricQuestProof.hostile(target,actor) && t.hasUUID("actor") && t.getUUID("actor").equals(actor.getUUID()) && t.hasUUID("projectile") && t.getUUID("projectile").equals(projectile.getUUID()) && t.getString("ammo").equals("unearthed_journey:tipped_blow_dart") && t.getString("weapon").equals("unearthed_journey:bamboo_blowgun"))HIT.set(new Hit(actor,projectile,target));}
 public static void poison(LivingEntity victim,MobEffectInstance effect,boolean accepted){var hit=HIT.get();if(hit!=null && victim==hit.target && accepted && effect.getEffect()==MobEffects.POISON && victim.hasEffect(MobEffects.POISON))hit.poison=true;}
 public static void afterHit(Projectile projectile){var hit=HIT.get();HIT.remove();if(hit!=null && hit.projectile==projectile && hit.poison && hit.damage && projectile.getOwner()==hit.actor && WorldPrehistoricQuestProof.actor(hit.actor)!=null && WorldPrehistoricQuestProof.hostile(hit.target,hit.actor) && Float.isFinite(hit.health) && Float.isFinite(hit.absorption) && Float.isFinite(hit.target.getHealth()) && Float.isFinite(hit.target.getAbsorptionAmount()) && (hit.target.getHealth()<hit.health || hit.target.getAbsorptionAmount()<hit.absorption))WorldPrehistoricQuestProof.emit(hit.actor,"v3_era_quiet_dart");}
}
